package application.alignment;import behavior.alignment.analysis.*;import behavior.alignment.profile.*;import behavior.alignment.repository.*;import behavior.evidence.repository.BehaviorEvidenceSetRepository;import operationalControl.profile.ValerianProfessionCreditProfiles;import java.util.*;
/** Rebuilds M3.4 compatibility maps from immutable M3.3 case files. */
public final class StructuralAlignmentService{private final BehaviorEvidenceSetRepository cases;private final StructuralAlignmentRepository alignments;private final StructuralAlignmentAnalyzer analyzer;private StructuralAlignmentAnalysisReport lastReport=new StructuralAlignmentAnalysisReport(0,0,0,0,0,0,List.of());public StructuralAlignmentService(BehaviorEvidenceSetRepository cases,StructuralAlignmentRepository alignments,StructuralAlignmentAnalyzer analyzer){this.cases=Objects.requireNonNull(cases);this.alignments=Objects.requireNonNull(alignments);this.analyzer=Objects.requireNonNull(analyzer);}public StructuralAlignmentAnalysisReport rebuild(){lastReport=analyzer.analyze(cases.findAll(),ValerianProfessionCreditProfiles.all());alignments.replaceAll(lastReport.alignments());return lastReport;}public StructuralAlignmentAnalysisReport lastReport(){return lastReport;}public Optional<StructuralAlignment> findById(StructuralAlignmentId id){return alignments.findById(id);}public List<StructuralAlignment> findAll(){return alignments.findAll();}public long count(){return alignments.count();}}
